export class HierarchicalCoordinationSystem {
  constructor(thresholds) {
    this.thresholds = thresholds;
    this.escalationLog = [];
  }

  evaluateTask(task) {
    const { priority, complexity } = task;
    const threshold = this.thresholds[priority] || 0;

    if (complexity > threshold) {
      this.escalateTask(task);
      return 'escalated';
    }
    return 'handled';
  }

  escalateTask(task) {
    this.escalationLog.push(task);
    console.log(`Task ${task.id} escalated due to complexity ${task.complexity}.`);
  }
}

// Example usage
const thresholds = { low: 10, medium: 20, high: 30 };
const hcs = new HierarchicalCoordinationSystem(thresholds);
const task = { id: 1, priority: 'medium', complexity: 25 };
hcs.evaluateTask(task);